import { defineConfig, devices } from "@playwright/test";

/**
 * UI interaction verification harness (specs/changes/2026-11-01-ui-interaction-verification).
 *
 * Runs the five baseline surfaces against the real `serve` carrier (real SQLite +
 * deterministic fake upstream) with human-like role/keyboard journeys. Every test
 * is tagged `@interaction:<ID>` and writes an evidence JSON on success; snapshots
 * live in-repo and are only regenerated by a human via `pnpm e2e:ui:update`.
 *
 * Offline/deterministic by design (docs/11 §8.6): workers 1, retries 0, zh-CN,
 * light, reduced motion, animations/caret frozen for the visual baseline.
 */
const SERVE_URL = "http://127.0.0.1:8788";
const EVIDENCE_ROOT = "target/evidence/2026-11-01-ui-interaction-verification";

export default defineConfig({
  testDir: "e2e/interaction",
  timeout: 90_000,
  expect: {
    timeout: 20_000,
    toHaveScreenshot: {
      animations: "disabled",
      caret: "hide",
      maxDiffPixelRatio: 0.002,
      // Screenshot baselines are committed under `e2e/interaction/__screenshots__/`
      // (design.md §2.1); the top-level template stays for aria snapshot files.
      pathTemplate: "{testDir}/__screenshots__/{testFilePath}/{arg}{ext}",
    },
  },
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: [
    ["list"],
    ["html", { outputFolder: `${EVIDENCE_ROOT}/playwright-report`, open: "never" }],
  ],
  use: {
    baseURL: SERVE_URL,
    locale: "zh-CN",
    colorScheme: "light",
    reducedMotion: "reduce",
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    video: "off",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"], viewport: { width: 1280, height: 820 } } }],
  snapshotPathTemplate: "{testDir}/__snapshots__/{testFilePath}/{arg}{ext}",
  webServer: {
    // Deterministic fake upstream + baseline git workspace + real serve/SQLite,
    // built from the committed personal baseline (never reused stale).
    command: "bash e2e/serve-m1.sh",
    url: `${SERVE_URL}/healthz`,
    reuseExistingServer: false,
    timeout: 300_000,
  },
});
